head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > isPopup]<br/>현재 윈도우가 팝업 창인지 판별하여 결과를 반환합니다.",
    "validation" : [
        "현재 윈도우가 팝업 창이면 true 를 반환해야 합니다.",
        "현재 윈도우가 팝업 창이 아니면 false 를 반환해야 합니다.",
        "예외 발생 시 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_isPopup_onclick = function () {
    let ret = WebSquare.util.isPopup();
    wf_body_bottom.getObj("scwin").setReturnValue("isPopup() : " + ret);
}

scwin.btn_isPopup_popup_onclick = function () {
    WebSquare.util.createPopup(
        "isPopup_popup",
        "browser",
        "isPopup 테스트 팝업",
        "width=500,height=200,top=100,left=100",
        true,
        false,
        "/sample/common_link/util_isPopup_1.xml",
        "WebSquare1.xml",
        undefined,
        "map",
        undefined
    );
}
